import pandas as pd
import requests
from datetime import datetime, timezone

now = datetime.now(timezone.utc)
now_epoch = int(now.timestamp())

EXPECTED_COLUMNS = [
    'country_code', 'country_name', 'indicator_id', 'indicator_name',
    'year', 'value', 'growth_tier', 'investability_tag',
    'etf_hint', 'economic_thesis', '_epoch',
]

INDICATORS = [
    {'id': 'NY.GDP.MKTP.KD.ZG', 'name': 'GDP growth (annual %)'},
    {'id': 'FP.CPI.TOTL.ZG', 'name': 'Inflation, consumer prices (annual %)'},
    {'id': 'NE.EXP.GNFS.KD.ZG', 'name': 'Exports of goods and services growth (annual %)'},
]

ETF_MAP = {
    'BRA': 'EWZ', 'IND': 'INDA', 'CHN': 'FXI', 'MEX': 'EWW',
    'ZAF': 'EZA', 'TUR': 'TUR', 'IDN': 'EIDO', 'PHL': 'EPHE',
    'POL': 'EPOL', 'THA': 'THD', 'VNM': 'VNM', 'TWN': 'EWT',
    'KOR': 'EWY', 'JPN': 'EWJ', 'ARG': 'ARGT', 'CHL': 'ECH',
    'COL': 'GXG', 'PER': 'EPU', 'MYS': 'EWM', 'EGY': 'EGPT',
    'NGA': 'NGE', 'SAU': 'KSA', 'ARE': 'UAE', 'QAT': 'QAT',
    'PAK': 'PAK', 'USA': 'SPY', 'GBR': 'EWU', 'DEU': 'EWG',
    'FRA': 'EWQ', 'ITA': 'EWI', 'ESP': 'EWP', 'NLD': 'EWN',
    'CAN': 'EWC', 'AUS': 'EWA', 'HKG': 'EWH', 'SGP': 'EWS',
    'CHE': 'EWL', 'SWE': 'EWD',
}

EMERGING = ['BRA','IND','CHN','MEX','ZAF','TUR','IDN','PHL','POL','THA','VNM','TWN','KOR','ARG','CHL','COL','PER','MYS','EGY','NGA','SAU','ARE','QAT','HUN','PAK','BGD','RUS','UKR','CZE','ROU','BGR','HRV','KAZ','UZB','KEN','MAR','TUN','VEN','ECU','URY','LKA','ETH']
DEVELOPED = ['USA', 'GBR', 'DEU', 'FRA', 'ITA', 'ESP', 'NLD', 'BEL', 'SWE', 'NOR', 'DNK', 'FIN', 'CAN', 'AUS', 'NZL', 'CHE', 'SGP', 'HKG', 'IRL', 'JPN']
SKIP_AGG = ['WLD','HIC','LIC','LMC','UMC','MIC','HPC','OED','LDC','EMU','ARB','CEB','EAP','EAS','ECA','ECS','EUU','LCN','LAC','MEA','MNA','NAC','SAS','SSF','SSA','TEA','TEC','TLA','TMN','TSA','TSS','AFE','AFW','CSS','PSS','PST','PRE','FCS','IDA','IBD','IBT','IDB','IDX','INX','LTE','SST','XKX']

def growth_tier_for(value, indicator_id):
    if value is None:
        return 'UNKNOWN'
    if indicator_id == 'FP.CPI.TOTL.ZG':
        if value >= 25.0:
            return 'HYPERINFLATION'
        if value >= 10.0:
            return 'HIGH'
        if value >= 4.0:
            return 'ELEVATED'
        if value >= 0.0:
            return 'NORMAL'
        return 'DEFLATION'
    if value >= 7.0:
        return 'EXPLOSIVE'
    if value >= 5.0:
        return 'STRONG'
    if value >= 3.0:
        return 'STEADY'
    if value >= 0.0:
        return 'SLUGGISH'
    return 'CONTRACTING'

def investability_for(iso3):
    if iso3 in EMERGING:
        return 'INVESTABLE_EM'
    if iso3 in DEVELOPED:
        return 'DEVELOPED'
    return 'FRONTIER'

def thesis_for(indicator_id, tier):
    if indicator_id == 'NY.GDP.MKTP.KD.ZG':
        if tier == 'EXPLOSIVE':
            return 'Overweight: fast-growing economy - country ETF long, local currency carry'
        if tier == 'STRONG':
            return 'Overweight: sustained expansion - country ETF, frontier debt'
        if tier == 'STEADY':
            return 'Neutral overweight: track inflation + reserves for divergence'
        if tier == 'CONTRACTING':
            return 'Underweight: recession risk - short country ETF, long USD'
        return 'Neutral: low growth, limited edge'
    if indicator_id == 'FP.CPI.TOTL.ZG':
        if tier == 'HYPERINFLATION':
            return 'Currency collapse risk - short local FX, consider gold/USD'
        if tier == 'HIGH':
            return 'Central bank tightening imminent - short local bonds, long USD'
        if tier == 'DEFLATION':
            return 'Deflation risk - long local bonds, defensive equities'
        return 'Inflation within normal range'
    if indicator_id == 'NE.EXP.GNFS.KD.ZG':
        if tier == 'EXPLOSIVE' or tier == 'STRONG':
            return 'Export-led growth - watch commodity/manufacturing ETFs'
        if tier == 'CONTRACTING':
            return 'Export collapse - global demand weakening signal'
        return 'Trade balance stable'
    return 'Macro indicator - track vs trend'

rows = []
for ii in range(len(INDICATORS)):
    ind = INDICATORS[ii]
    ind_id = ind['id']
    ind_name = ind['name']
    try:
        resp = requests.get(
            'https://api.worldbank.org/v2/country/all/indicator/' + ind_id,
            params={'format': 'json', 'per_page': 400, 'mrv': 3},
            headers={'User-Agent': 'speakesquery (macro-brief) ingestion'},
            timeout=60,
        )
        resp.raise_for_status()
        payload = resp.json()
    except Exception:
        continue
    if not isinstance(payload, list) or len(payload) < 2:
        continue
    data_list = payload[1]
    if not isinstance(data_list, list):
        continue
    seen_codes = {}
    for di in range(len(data_list)):
        obs = data_list[di]
        if not isinstance(obs, dict):
            continue
        iso3_raw = obs.get('countryiso3code', '')
        iso3 = str(iso3_raw or '').upper()
        if not iso3 or len(iso3) != 3:
            continue
        if iso3 in SKIP_AGG:
            continue
        if iso3 in seen_codes:
            continue
        value_raw = obs.get('value')
        if value_raw is None:
            continue
        try:
            value = float(value_raw)
        except Exception:
            continue
        country_obj = obs.get('country') or {}
        country_name = ''
        if isinstance(country_obj, dict):
            country_name = str(country_obj.get('value', '') or '')
        year = str(obs.get('date', '') or '')
        tier = growth_tier_for(value, ind_id)
        seen_codes[iso3] = 1
        rows.append({
            'country_code': iso3,
            'country_name': country_name,
            'indicator_id': ind_id,
            'indicator_name': ind_name,
            'year': year,
            'value': round(value, 3),
            'growth_tier': tier,
            'investability_tag': investability_for(iso3),
            'etf_hint': ETF_MAP.get(iso3, ''),
            'economic_thesis': thesis_for(ind_id, tier),
            '_epoch': now_epoch,
        })

if rows:
    df = pd.DataFrame(rows, columns=EXPECTED_COLUMNS)
    df = df.sort_values(['indicator_id', 'value'], ascending=[True, False]).reset_index(drop=True)
else:
    df = pd.DataFrame(columns=EXPECTED_COLUMNS)

